public abstract class Dispositivo {
    protected String codigo;
    protected Oficina oficina;
    protected double potenciaNominal;
    protected boolean encendido;
    protected double consumoDiario;


    // Constructor default
    public Dispositivo() {
        codigo = "";
        oficina = null;
        potenciaNominal = 0;
        encendido = false;
        consumoDiario = 0;
    }


    // Constructor completo

    public Dispositivo(String codigo, Oficina oficina, double potenciaNominal) {
        this.codigo = codigo;
        this.oficina = oficina;
        this.potenciaNominal = potenciaNominal;
        encendido = false;
        consumoDiario = 0;
    }

// Getters, mismo criterio que antes

    public String getCodigo() {
        return codigo;
    }

    public Oficina getOficina() {
        return oficina;
    }

    public double getPotenciaNominal() {
        return potenciaNominal;
    }

    public boolean getEncendido() {
        return encendido;
    }

    public double getConsumoDiario() {
        return consumoDiario;
    }


    // Consumo por hora. Pero es abstracto, pues cambia por subtipo de dispositivo

    public abstract double calcularConsumoHora();


    // Calcula el consumo de una hora

    public double procesarHora() {
        double consumo = calcularConsumoHora();
        consumoDiario += consumo;
        return consumo;
    }


    // Reset de las 24 horas

    public void reiniciarConsumo() {
        consumoDiario = 0;
    }


    // toString

    @Override
    public String toString() {

        String estado;
        if (encendido) {
            estado = "Encendido";
        }
        else {
            estado = "Apagado";
        }
        return "Codigo: " + codigo
                + "\nOficina: " + oficina.getCodigo()
                + "\nPotencia nominal: " + potenciaNominal + " W"
                + "\nEstado: " + estado
                + "\nConsumo diario: " + consumoDiario + " kWh";
    }
}
